function gd_decodeBase64(str){
  var chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  str=str.replace(/=+$/,'');
  var result='';var i=0;
  while(i<str.length){
    var e1=chars.indexOf(str.charAt(i));
    var e2=chars.indexOf(str.charAt(i+1));
    var e3=str.charAt(i+2)?chars.indexOf(str.charAt(i+2)):-1;
    var e4=str.charAt(i+3)?chars.indexOf(str.charAt(i+3)):-1;
    if(e1<0||e2<0)throw 'bad b64';
    result+=String.fromCharCode((e1<<2)|(e2>>4));
    if(e3>=0)result+=String.fromCharCode(((e2&15)<<4)|(e3>>2));
    if(e4>=0)result+=String.fromCharCode(((e3&3)<<6)|e4);
    i+=4;
  }
  return result;
}
function gd_decodeChapterImages(input){
  var STD='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  var CUSTOM='_-9876543210abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var body=input.substring(3,input.length-2);
  var aLen=Math.floor((body.length-5)/3);
  var bLen=Math.floor((body.length-5-aLen)/2);
  var cLen=body.length-5-aLen-bLen;
  var part1=body.substring(0,bLen);
  var part2=body.substring(bLen+2,bLen+2+cLen);
  var part3=body.substring(bLen+2+cLen+3);
  var reordered=part3+part1+part2;
  var un='';
  for(var i=0,block=0;i<reordered.length;i+=7,block++){
    var chunk=reordered.substring(i,Math.min(i+7,reordered.length));
    un+=(block%2===1)?chunk.split('').reverse().join(''):chunk;
  }
  var std='';
  for(var i=0;i<un.length;i++){
    var code=un.charCodeAt(i);
    var idx=CUSTOM.indexOf(un.charAt(i));
    if(idx<0)throw 'bad char';
    std+=STD.charAt(idx);
  }
  var b64=std.replace(/-/g,'+').replace(/_/g,'/');
  return JSON.parse(gd_decodeBase64(b64));
}

