ruleToc.chapterList:
@js:(function(){
var m=result.match(/id="mangachapters"[^>]*data-mid="(\d+)"/);
if(!m)return [];
var mid=m[1];
var resp=java.ajax('https://v2.apikk.top/api/v2/manga/get?mid='+mid+'&mode=all&t='+Date.now());
var jd=JSON.parse(resp);
var out=[];
if(jd&&jd.data&&jd.data.chapters){
  for(var i=0;i<jd.data.chapters.length;i++){
    var ch=jd.data.chapters[i];
    if(ch.id!=null&&ch.attributes&&ch.attributes.title!=null){
      out.push({name:String(ch.attributes.title),url:'https://v2.apikk.top/api/v2/chapter/getinfo?m='+mid+'&c='+ch.id});
    }
  }
}
return out;})()

